<?php require "../config/auth.php";require "../config/database.php";if($_SERVER["REQUEST_METHOD"]==="POST"){$vals=[];foreach(["nama", "divisi", "deskripsi", "status", "tahun", "waktu", "tempat", "banner", "detail"] as $c)$vals[]=$_POST[$c]??"";$pdo->prepare("INSERT INTO program_kerja (nama,divisi,deskripsi,status,tahun,waktu,tempat,banner,detail) VALUES (?,?,?,?,?,?,?,?,?)")->execute($vals);header("Location:program.php");exit;}if(isset($_GET["delete"])){$pdo->prepare("DELETE FROM program_kerja WHERE id=?")->execute([(int)$_GET["delete"]]);header("Location:program.php");exit;}$rows=$pdo->query("SELECT * FROM program_kerja ORDER BY id DESC")->fetchAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Program Kerja | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between"><h2>Program Kerja</h2><a href="index.php">Dashboard</a></div><div class="card p-4 my-4"><form method="post" class="row g-3"><div class="col-md-6"><label class="form-label">Nama</label><input name="nama" class="form-control"></div><div class="col-md-6"><label class="form-label">Divisi</label><input name="divisi" class="form-control"></div><div class="col-md-6"><label class="form-label">Deskripsi</label><input name="deskripsi" class="form-control"></div><div class="col-md-6"><label class="form-label">Status</label><input name="status" class="form-control"></div><div class="col-md-6"><label class="form-label">Tahun</label><input name="tahun" class="form-control"></div><div class="col-md-6"><label class="form-label">Waktu</label><input name="waktu" class="form-control"></div><div class="col-md-6"><label class="form-label">Tempat</label><input name="tempat" class="form-control"></div><div class="col-md-6"><label class="form-label">Banner</label><input name="banner" class="form-control"></div><div class="col-md-6"><label class="form-label">Detail</label><input name="detail" class="form-control"></div><div class="col-12"><button class="btn btn-primary">Tambah</button></div></form></div><div class="table-responsive"><table class="table table-striped"><thead><tr><th>ID</th><th>nama</th><th>divisi</th><th>deskripsi</th><th>status</th><th>tahun</th><th>waktu</th><th>tempat</th><th>banner</th><th>detail</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=e($r["nama"])?></td><td><?=e($r["divisi"])?></td><td><?=e($r["deskripsi"])?></td><td><?=e($r["status"])?></td><td><?=e($r["tahun"])?></td><td><?=e($r["waktu"])?></td><td><?=e($r["tempat"])?></td><td><?=e($r["banner"])?></td><td><?=e($r["detail"])?></td><td><a class="btn btn-sm btn-danger" href="?delete=<?=$r["id"]?>" onclick="return confirm('Hapus data?')">Hapus</a></td></tr><?php endforeach;?></tbody></table></div></div></body></html>